\set ON_ERROR_STOP on
BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL search_path=pg_catalog;
SET LOCAL datestyle='ISO, YMD';
SET LOCAL standard_conforming_strings=on;
SET LOCAL statement_timeout='15min';
SET LOCAL lock_timeout='5s';
SELECT set_config('olist.expected_database','inteligencia_receita_db',true) IS NOT NULL;
SELECT json_build_object('database',current_database(),'version',current_setting('server_version'),'read_only',current_setting('transaction_read_only'),'isolation',current_setting('transaction_isolation'),'marker',shobj_description(oid,'pg_database')) FROM pg_database WHERE datname=current_database();
SELECT json_build_object('marco','antes');
SELECT json_build_object('fact','fato_pedidos','silver_rows',(SELECT count(*) FROM silver."olist_orders_dataset"),'rows',count(*),'money',json_build_object(),'fk_members',json_build_object('cliente_sk',json_build_object('nao_informado',count(*) FILTER(WHERE "cliente_sk"=-1),'referencia_nao_encontrada',count(*) FILTER(WHERE "cliente_sk"=-2)),'localizacao_sk',json_build_object('nao_informado',count(*) FILTER(WHERE "localizacao_sk"=-1),'referencia_nao_encontrada',count(*) FILTER(WHERE "localizacao_sk"=-2)),'data_compra_sk',json_build_object('nao_informado',count(*) FILTER(WHERE "data_compra_sk"=-1),'referencia_nao_encontrada',count(*) FILTER(WHERE "data_compra_sk"=-2)),'data_aprovacao_sk',json_build_object('nao_informado',count(*) FILTER(WHERE "data_aprovacao_sk"=-1),'referencia_nao_encontrada',count(*) FILTER(WHERE "data_aprovacao_sk"=-2)),'data_transportadora_sk',json_build_object('nao_informado',count(*) FILTER(WHERE "data_transportadora_sk"=-1),'referencia_nao_encontrada',count(*) FILTER(WHERE "data_transportadora_sk"=-2)),'data_entrega_sk',json_build_object('nao_informado',count(*) FILTER(WHERE "data_entrega_sk"=-1),'referencia_nao_encontrada',count(*) FILTER(WHERE "data_entrega_sk"=-2)),'data_previsao_entrega_sk',json_build_object('nao_informado',count(*) FILTER(WHERE "data_previsao_entrega_sk"=-1),'referencia_nao_encontrada',count(*) FILTER(WHERE "data_previsao_entrega_sk"=-2))),'fingerprint',encode(sha256(convert_to(string_agg(row_to_json(x)::text,'' ORDER BY "order_id"),'UTF8')),'hex')) FROM (SELECT "order_id","customer_id","order_status","order_purchase_timestamp","order_approved_at","order_delivered_carrier_date","order_delivered_customer_date","order_estimated_delivery_date","cliente_sk","localizacao_sk","data_compra_sk","data_aprovacao_sk","data_transportadora_sk","data_entrega_sk","data_previsao_entrega_sk" FROM gold."fato_pedidos") x;
SELECT json_build_object('fact','fato_pedidos','statuses',json_object_agg(order_status,n)) FROM (SELECT order_status,count(*) n FROM gold."fato_pedidos" GROUP BY order_status) q;
SELECT json_build_object('fact','fato_itens_pedido','silver_rows',(SELECT count(*) FROM silver."olist_order_items_dataset"),'rows',count(*),'money',json_build_object('price',sum("price")::text,'freight_value',sum("freight_value")::text),'fk_members',json_build_object('cliente_sk',json_build_object('nao_informado',count(*) FILTER(WHERE "cliente_sk"=-1),'referencia_nao_encontrada',count(*) FILTER(WHERE "cliente_sk"=-2)),'localizacao_sk',json_build_object('nao_informado',count(*) FILTER(WHERE "localizacao_sk"=-1),'referencia_nao_encontrada',count(*) FILTER(WHERE "localizacao_sk"=-2)),'produto_sk',json_build_object('nao_informado',count(*) FILTER(WHERE "produto_sk"=-1),'referencia_nao_encontrada',count(*) FILTER(WHERE "produto_sk"=-2)),'vendedor_sk',json_build_object('nao_informado',count(*) FILTER(WHERE "vendedor_sk"=-1),'referencia_nao_encontrada',count(*) FILTER(WHERE "vendedor_sk"=-2)),'data_compra_sk',json_build_object('nao_informado',count(*) FILTER(WHERE "data_compra_sk"=-1),'referencia_nao_encontrada',count(*) FILTER(WHERE "data_compra_sk"=-2)),'data_limite_envio_sk',json_build_object('nao_informado',count(*) FILTER(WHERE "data_limite_envio_sk"=-1),'referencia_nao_encontrada',count(*) FILTER(WHERE "data_limite_envio_sk"=-2))),'fingerprint',encode(sha256(convert_to(string_agg(row_to_json(x)::text,'' ORDER BY "order_id","order_item_id"),'UTF8')),'hex')) FROM (SELECT "order_id","order_item_id","product_id","seller_id","shipping_limit_date","price","freight_value","customer_id","order_status","order_purchase_timestamp","cliente_sk","localizacao_sk","produto_sk","vendedor_sk","data_compra_sk","data_limite_envio_sk" FROM gold."fato_itens_pedido") x;
SELECT json_build_object('fact','fato_itens_pedido','statuses',json_object_agg(order_status,n)) FROM (SELECT order_status,count(*) n FROM gold."fato_itens_pedido" GROUP BY order_status) q;
SELECT json_build_object('fact','fato_pagamentos','silver_rows',(SELECT count(*) FROM silver."olist_order_payments_dataset"),'rows',count(*),'money',json_build_object('payment_value',sum("payment_value")::text),'fk_members',json_build_object('cliente_sk',json_build_object('nao_informado',count(*) FILTER(WHERE "cliente_sk"=-1),'referencia_nao_encontrada',count(*) FILTER(WHERE "cliente_sk"=-2)),'localizacao_sk',json_build_object('nao_informado',count(*) FILTER(WHERE "localizacao_sk"=-1),'referencia_nao_encontrada',count(*) FILTER(WHERE "localizacao_sk"=-2)),'forma_pagamento_sk',json_build_object('nao_informado',count(*) FILTER(WHERE "forma_pagamento_sk"=-1),'referencia_nao_encontrada',count(*) FILTER(WHERE "forma_pagamento_sk"=-2)),'data_compra_sk',json_build_object('nao_informado',count(*) FILTER(WHERE "data_compra_sk"=-1),'referencia_nao_encontrada',count(*) FILTER(WHERE "data_compra_sk"=-2))),'fingerprint',encode(sha256(convert_to(string_agg(row_to_json(x)::text,'' ORDER BY "order_id","payment_sequential"),'UTF8')),'hex')) FROM (SELECT "order_id","payment_sequential","payment_type","payment_installments","payment_value","customer_id","order_status","order_purchase_timestamp","cliente_sk","localizacao_sk","forma_pagamento_sk","data_compra_sk" FROM gold."fato_pagamentos") x;
SELECT json_build_object('fact','fato_pagamentos','statuses',json_object_agg(order_status,n)) FROM (SELECT order_status,count(*) n FROM gold."fato_pagamentos" GROUP BY order_status) q;
SELECT json_build_object('reconciliation_orders',count(*),'without_items',count(*) FILTER(WHERE itens IS NULL),'without_payments',count(*) FILTER(WHERE pagamentos IS NULL),'compared',count(diferenca),'over_one_cent',count(*) FILTER(WHERE abs(diferenca)>0.01),'positive',count(*) FILTER(WHERE diferenca>0.01),'negative',count(*) FILTER(WHERE diferenca < -0.01),'min_delta',min(diferenca)::text,'max_delta',max(diferenca)::text) FROM (WITH i AS (SELECT order_id,count(*) itens,sum(price) preco,sum(freight_value) frete FROM gold."fato_itens_pedido" GROUP BY order_id),
p AS (SELECT order_id,count(*) pagamentos,sum(payment_value) valor FROM gold."fato_pagamentos" GROUP BY order_id)
SELECT o.order_id,o.order_status,i.itens,p.pagamentos,i.preco,i.frete,p.valor,
 CASE WHEN i.order_id IS NULL OR p.order_id IS NULL THEN NULL ELSE p.valor-i.preco-i.frete END diferenca
FROM gold."fato_pedidos" o LEFT JOIN i ON i.order_id=o.order_id LEFT JOIN p ON p.order_id=o.order_id) rec;
SELECT json_build_object('divergent_status',order_status,'orders',count(*)) FROM (WITH i AS (SELECT order_id,count(*) itens,sum(price) preco,sum(freight_value) frete FROM gold."fato_itens_pedido" GROUP BY order_id),
p AS (SELECT order_id,count(*) pagamentos,sum(payment_value) valor FROM gold."fato_pagamentos" GROUP BY order_id)
SELECT o.order_id,o.order_status,i.itens,p.pagamentos,i.preco,i.frete,p.valor,
 CASE WHEN i.order_id IS NULL OR p.order_id IS NULL THEN NULL ELSE p.valor-i.preco-i.frete END diferenca
FROM gold."fato_pedidos" o LEFT JOIN i ON i.order_id=o.order_id LEFT JOIN p ON p.order_id=o.order_id) rec WHERE abs(diferenca)>0.01 GROUP BY order_status ORDER BY order_status;
SELECT json_build_object('dimension','dim_clientes','source_distinct',count(*)) FROM (SELECT "customer_unique_id" FROM (SELECT DISTINCT customer_unique_id FROM silver.olist_customers_dataset WHERE customer_unique_id IS NOT NULL) origem) x;
SELECT json_build_object('dimension','dim_clientes','rows',count(*),'regular',count(*) FILTER(WHERE membro_tipo='regular'),'nao_informado',count(*) FILTER(WHERE membro_tipo='nao_informado'),'referencia_nao_encontrada',count(*) FILTER(WHERE membro_tipo='referencia_nao_encontrada'),'fingerprint',encode(sha256(convert_to(string_agg(row_to_json(x)::text,'' ORDER BY "cliente_sk"),'UTF8')),'hex')) FROM (SELECT "cliente_sk","customer_unique_id","membro_tipo" FROM gold."dim_clientes") x;
SELECT json_build_object('dimension','dim_produtos','source_distinct',count(*)) FROM (SELECT "product_id","product_category_name","product_name_lenght","product_description_lenght","product_photos_qty","product_weight_g","product_length_cm","product_height_cm","product_width_cm","product_category_name_english" FROM (SELECT p.*,t.product_category_name_english FROM silver.olist_products_dataset p LEFT JOIN silver.product_category_name_translation t ON t.product_category_name=p.product_category_name WHERE p.product_id IS NOT NULL) origem) x;
SELECT json_build_object('dimension','dim_produtos','rows',count(*),'regular',count(*) FILTER(WHERE membro_tipo='regular'),'nao_informado',count(*) FILTER(WHERE membro_tipo='nao_informado'),'referencia_nao_encontrada',count(*) FILTER(WHERE membro_tipo='referencia_nao_encontrada'),'fingerprint',encode(sha256(convert_to(string_agg(row_to_json(x)::text,'' ORDER BY "produto_sk"),'UTF8')),'hex')) FROM (SELECT "produto_sk","product_id","product_category_name","product_name_lenght","product_description_lenght","product_photos_qty","product_weight_g","product_length_cm","product_height_cm","product_width_cm","product_category_name_english","membro_tipo" FROM gold."dim_produtos") x;
SELECT json_build_object('dimension','dim_vendedores','source_distinct',count(*)) FROM (SELECT "seller_id","seller_zip_code_prefix","seller_city","seller_state" FROM (SELECT * FROM silver.olist_sellers_dataset WHERE seller_id IS NOT NULL) origem) x;
SELECT json_build_object('dimension','dim_vendedores','rows',count(*),'regular',count(*) FILTER(WHERE membro_tipo='regular'),'nao_informado',count(*) FILTER(WHERE membro_tipo='nao_informado'),'referencia_nao_encontrada',count(*) FILTER(WHERE membro_tipo='referencia_nao_encontrada'),'fingerprint',encode(sha256(convert_to(string_agg(row_to_json(x)::text,'' ORDER BY "vendedor_sk"),'UTF8')),'hex')) FROM (SELECT "vendedor_sk","seller_id","seller_zip_code_prefix","seller_city","seller_state","membro_tipo" FROM gold."dim_vendedores") x;
SELECT json_build_object('dimension','dim_calendario','source_distinct',count(*)) FROM (WITH limites AS (SELECT min(dia) inicio,max(dia) fim FROM (SELECT "order_purchase_timestamp"::date AS dia FROM silver."olist_orders_dataset" WHERE "order_purchase_timestamp" IS NOT NULL UNION ALL SELECT "order_approved_at"::date AS dia FROM silver."olist_orders_dataset" WHERE "order_approved_at" IS NOT NULL UNION ALL SELECT "order_delivered_carrier_date"::date AS dia FROM silver."olist_orders_dataset" WHERE "order_delivered_carrier_date" IS NOT NULL UNION ALL SELECT "order_delivered_customer_date"::date AS dia FROM silver."olist_orders_dataset" WHERE "order_delivered_customer_date" IS NOT NULL UNION ALL SELECT "order_estimated_delivery_date"::date AS dia FROM silver."olist_orders_dataset" WHERE "order_estimated_delivery_date" IS NOT NULL UNION ALL SELECT "shipping_limit_date"::date AS dia FROM silver."olist_order_items_dataset" WHERE "shipping_limit_date" IS NOT NULL) d), dias AS (SELECT inicio+g AS dia FROM limites CROSS JOIN LATERAL generate_series(0,fim-inicio) g) SELECT dia,extract(year FROM dia)::integer ano,extract(month FROM dia)::integer mes,extract(day FROM dia)::integer dia_mes FROM dias) x;
SELECT json_build_object('dimension','dim_calendario','rows',count(*),'regular',count(*) FILTER(WHERE membro_tipo='regular'),'nao_informado',count(*) FILTER(WHERE membro_tipo='nao_informado'),'referencia_nao_encontrada',count(*) FILTER(WHERE membro_tipo='referencia_nao_encontrada'),'fingerprint',encode(sha256(convert_to(string_agg(row_to_json(x)::text,'' ORDER BY "data_sk"),'UTF8')),'hex')) FROM (SELECT "data_sk","dia","ano","mes","dia_mes","membro_tipo" FROM gold."dim_calendario") x;
SELECT json_build_object('dimension','dim_localizacao','source_distinct',count(*)) FROM (SELECT "customer_zip_code_prefix","customer_city","customer_state" FROM (SELECT DISTINCT c.customer_zip_code_prefix,c.customer_city,c.customer_state FROM silver.olist_orders_dataset o JOIN silver.olist_customers_dataset c ON c.customer_id=o.customer_id WHERE c.customer_zip_code_prefix IS NOT NULL AND c.customer_city IS NOT NULL AND c.customer_state IS NOT NULL) origem) x;
SELECT json_build_object('dimension','dim_localizacao','rows',count(*),'regular',count(*) FILTER(WHERE membro_tipo='regular'),'nao_informado',count(*) FILTER(WHERE membro_tipo='nao_informado'),'referencia_nao_encontrada',count(*) FILTER(WHERE membro_tipo='referencia_nao_encontrada'),'fingerprint',encode(sha256(convert_to(string_agg(row_to_json(x)::text,'' ORDER BY "localizacao_sk"),'UTF8')),'hex')) FROM (SELECT "localizacao_sk","customer_zip_code_prefix","customer_city","customer_state","membro_tipo" FROM gold."dim_localizacao") x;
SELECT json_build_object('dimension','dim_forma_pagamento','source_distinct',count(*)) FROM (SELECT "payment_type" FROM (SELECT DISTINCT payment_type FROM silver.olist_order_payments_dataset WHERE payment_type IS NOT NULL) origem) x;
SELECT json_build_object('dimension','dim_forma_pagamento','rows',count(*),'regular',count(*) FILTER(WHERE membro_tipo='regular'),'nao_informado',count(*) FILTER(WHERE membro_tipo='nao_informado'),'referencia_nao_encontrada',count(*) FILTER(WHERE membro_tipo='referencia_nao_encontrada'),'fingerprint',encode(sha256(convert_to(string_agg(row_to_json(x)::text,'' ORDER BY "forma_pagamento_sk"),'UTF8')),'hex')) FROM (SELECT "forma_pagamento_sk","payment_type","membro_tipo" FROM gold."dim_forma_pagamento") x;
SELECT json_build_object('calendar_min',min(dia),'calendar_max',max(dia),'observed_distinct_days',count(DISTINCT dia)) FROM (SELECT "order_purchase_timestamp"::date AS dia FROM silver."olist_orders_dataset" WHERE "order_purchase_timestamp" IS NOT NULL UNION ALL SELECT "order_approved_at"::date AS dia FROM silver."olist_orders_dataset" WHERE "order_approved_at" IS NOT NULL UNION ALL SELECT "order_delivered_carrier_date"::date AS dia FROM silver."olist_orders_dataset" WHERE "order_delivered_carrier_date" IS NOT NULL UNION ALL SELECT "order_delivered_customer_date"::date AS dia FROM silver."olist_orders_dataset" WHERE "order_delivered_customer_date" IS NOT NULL UNION ALL SELECT "order_estimated_delivery_date"::date AS dia FROM silver."olist_orders_dataset" WHERE "order_estimated_delivery_date" IS NOT NULL UNION ALL SELECT "shipping_limit_date"::date AS dia FROM silver."olist_order_items_dataset" WHERE "shipping_limit_date" IS NOT NULL) d;
SELECT json_build_object('products_category_null',count(*) FILTER(WHERE p.product_category_name IS NULL),'products_translation_missing',count(*) FILTER(WHERE p.product_category_name IS NOT NULL AND t.product_category_name IS NULL)) FROM silver.olist_products_dataset p LEFT JOIN silver.product_category_name_translation t USING(product_category_name);
SELECT json_build_object('partial_locations',count(*)) FROM silver.olist_orders_dataset o JOIN silver.olist_customers_dataset c USING(customer_id) WHERE c.customer_zip_code_prefix IS NULL OR c.customer_city IS NULL OR c.customer_state IS NULL;
SELECT json_build_object('resolution','pedidos_cliente','rows',count(*),'regular',count(*) FILTER(WHERE (CASE WHEN o.customer_id IS NULL THEN -1 WHEN c.customer_id IS NULL THEN -2 WHEN c.customer_unique_id IS NULL THEN -1 ELSE COALESCE(d.cliente_sk,-2) END)>0),'nao_informado',count(*) FILTER(WHERE (CASE WHEN o.customer_id IS NULL THEN -1 WHEN c.customer_id IS NULL THEN -2 WHEN c.customer_unique_id IS NULL THEN -1 ELSE COALESCE(d.cliente_sk,-2) END)=-1),'referencia_nao_encontrada',count(*) FILTER(WHERE (CASE WHEN o.customer_id IS NULL THEN -1 WHEN c.customer_id IS NULL THEN -2 WHEN c.customer_unique_id IS NULL THEN -1 ELSE COALESCE(d.cliente_sk,-2) END)=-2)) FROM silver.olist_orders_dataset o LEFT JOIN silver.olist_customers_dataset c ON c.customer_id=o.customer_id LEFT JOIN gold.dim_clientes d ON d.customer_unique_id=c.customer_unique_id;
SELECT json_build_object('resolution','pedidos_localizacao','rows',count(*),'regular',count(*) FILTER(WHERE (CASE WHEN o.customer_id IS NULL THEN -1 WHEN c.customer_id IS NULL THEN -2 WHEN c.customer_zip_code_prefix IS NULL OR c.customer_city IS NULL OR c.customer_state IS NULL THEN -1 ELSE COALESCE(d.localizacao_sk,-2) END)>0),'nao_informado',count(*) FILTER(WHERE (CASE WHEN o.customer_id IS NULL THEN -1 WHEN c.customer_id IS NULL THEN -2 WHEN c.customer_zip_code_prefix IS NULL OR c.customer_city IS NULL OR c.customer_state IS NULL THEN -1 ELSE COALESCE(d.localizacao_sk,-2) END)=-1),'referencia_nao_encontrada',count(*) FILTER(WHERE (CASE WHEN o.customer_id IS NULL THEN -1 WHEN c.customer_id IS NULL THEN -2 WHEN c.customer_zip_code_prefix IS NULL OR c.customer_city IS NULL OR c.customer_state IS NULL THEN -1 ELSE COALESCE(d.localizacao_sk,-2) END)=-2)) FROM silver.olist_orders_dataset o LEFT JOIN silver.olist_customers_dataset c ON c.customer_id=o.customer_id LEFT JOIN gold.dim_localizacao d ON d.customer_zip_code_prefix=c.customer_zip_code_prefix AND d.customer_city=c.customer_city AND d.customer_state=c.customer_state;
SELECT json_build_object('resolution','pagamentos_forma','rows',count(*),'regular',count(*) FILTER(WHERE (CASE WHEN p.payment_type IS NULL THEN -1 ELSE COALESCE(d.forma_pagamento_sk,-2) END)>0),'nao_informado',count(*) FILTER(WHERE (CASE WHEN p.payment_type IS NULL THEN -1 ELSE COALESCE(d.forma_pagamento_sk,-2) END)=-1),'referencia_nao_encontrada',count(*) FILTER(WHERE (CASE WHEN p.payment_type IS NULL THEN -1 ELSE COALESCE(d.forma_pagamento_sk,-2) END)=-2)) FROM silver.olist_order_payments_dataset p LEFT JOIN gold.dim_forma_pagamento d ON d.payment_type=p.payment_type;
SELECT json_build_object('resolution','itens_produto','rows',count(*),'regular',count(*) FILTER(WHERE (CASE WHEN i.product_id IS NULL THEN -1 ELSE COALESCE(d.produto_sk,-2) END)>0),'nao_informado',count(*) FILTER(WHERE (CASE WHEN i.product_id IS NULL THEN -1 ELSE COALESCE(d.produto_sk,-2) END)=-1),'referencia_nao_encontrada',count(*) FILTER(WHERE (CASE WHEN i.product_id IS NULL THEN -1 ELSE COALESCE(d.produto_sk,-2) END)=-2)) FROM silver.olist_order_items_dataset i LEFT JOIN gold.dim_produtos d ON d.product_id=i.product_id;
SELECT json_build_object('resolution','itens_vendedor','rows',count(*),'regular',count(*) FILTER(WHERE (CASE WHEN i.seller_id IS NULL THEN -1 ELSE COALESCE(d.vendedor_sk,-2) END)>0),'nao_informado',count(*) FILTER(WHERE (CASE WHEN i.seller_id IS NULL THEN -1 ELSE COALESCE(d.vendedor_sk,-2) END)=-1),'referencia_nao_encontrada',count(*) FILTER(WHERE (CASE WHEN i.seller_id IS NULL THEN -1 ELSE COALESCE(d.vendedor_sk,-2) END)=-2)) FROM silver.olist_order_items_dataset i LEFT JOIN gold.dim_vendedores d ON d.seller_id=i.seller_id;
SELECT json_build_object('resolution','itens_cliente','rows',count(*),'regular',count(*) FILTER(WHERE (CASE WHEN child.order_id IS NULL THEN -1 WHEN o.order_id IS NULL THEN -2 ELSE (CASE WHEN o.customer_id IS NULL THEN -1 WHEN c.customer_id IS NULL THEN -2 WHEN c.customer_unique_id IS NULL THEN -1 ELSE COALESCE(d.cliente_sk,-2) END) END)>0),'nao_informado',count(*) FILTER(WHERE (CASE WHEN child.order_id IS NULL THEN -1 WHEN o.order_id IS NULL THEN -2 ELSE (CASE WHEN o.customer_id IS NULL THEN -1 WHEN c.customer_id IS NULL THEN -2 WHEN c.customer_unique_id IS NULL THEN -1 ELSE COALESCE(d.cliente_sk,-2) END) END)=-1),'referencia_nao_encontrada',count(*) FILTER(WHERE (CASE WHEN child.order_id IS NULL THEN -1 WHEN o.order_id IS NULL THEN -2 ELSE (CASE WHEN o.customer_id IS NULL THEN -1 WHEN c.customer_id IS NULL THEN -2 WHEN c.customer_unique_id IS NULL THEN -1 ELSE COALESCE(d.cliente_sk,-2) END) END)=-2)) FROM silver."olist_order_items_dataset" child LEFT JOIN silver.olist_orders_dataset o ON o.order_id=child.order_id LEFT JOIN silver.olist_customers_dataset c ON c.customer_id=o.customer_id LEFT JOIN gold.dim_clientes d ON d.customer_unique_id=c.customer_unique_id;
SELECT json_build_object('resolution','itens_localizacao','rows',count(*),'regular',count(*) FILTER(WHERE (CASE WHEN child.order_id IS NULL THEN -1 WHEN o.order_id IS NULL THEN -2 ELSE (CASE WHEN o.customer_id IS NULL THEN -1 WHEN c.customer_id IS NULL THEN -2 WHEN c.customer_zip_code_prefix IS NULL OR c.customer_city IS NULL OR c.customer_state IS NULL THEN -1 ELSE COALESCE(d.localizacao_sk,-2) END) END)>0),'nao_informado',count(*) FILTER(WHERE (CASE WHEN child.order_id IS NULL THEN -1 WHEN o.order_id IS NULL THEN -2 ELSE (CASE WHEN o.customer_id IS NULL THEN -1 WHEN c.customer_id IS NULL THEN -2 WHEN c.customer_zip_code_prefix IS NULL OR c.customer_city IS NULL OR c.customer_state IS NULL THEN -1 ELSE COALESCE(d.localizacao_sk,-2) END) END)=-1),'referencia_nao_encontrada',count(*) FILTER(WHERE (CASE WHEN child.order_id IS NULL THEN -1 WHEN o.order_id IS NULL THEN -2 ELSE (CASE WHEN o.customer_id IS NULL THEN -1 WHEN c.customer_id IS NULL THEN -2 WHEN c.customer_zip_code_prefix IS NULL OR c.customer_city IS NULL OR c.customer_state IS NULL THEN -1 ELSE COALESCE(d.localizacao_sk,-2) END) END)=-2)) FROM silver."olist_order_items_dataset" child LEFT JOIN silver.olist_orders_dataset o ON o.order_id=child.order_id LEFT JOIN silver.olist_customers_dataset c ON c.customer_id=o.customer_id LEFT JOIN gold.dim_localizacao d ON d.customer_zip_code_prefix=c.customer_zip_code_prefix AND d.customer_city=c.customer_city AND d.customer_state=c.customer_state;
SELECT json_build_object('resolution','calendario_compra_itens','rows',count(*),'regular',count(*) FILTER(WHERE (CASE WHEN child.order_id IS NULL THEN -1 WHEN o.order_id IS NULL THEN -2 WHEN o.order_purchase_timestamp IS NULL THEN -1 ELSE COALESCE(d.data_sk,-2) END)>0),'nao_informado',count(*) FILTER(WHERE (CASE WHEN child.order_id IS NULL THEN -1 WHEN o.order_id IS NULL THEN -2 WHEN o.order_purchase_timestamp IS NULL THEN -1 ELSE COALESCE(d.data_sk,-2) END)=-1),'referencia_nao_encontrada',count(*) FILTER(WHERE (CASE WHEN child.order_id IS NULL THEN -1 WHEN o.order_id IS NULL THEN -2 WHEN o.order_purchase_timestamp IS NULL THEN -1 ELSE COALESCE(d.data_sk,-2) END)=-2)) FROM silver."olist_order_items_dataset" child LEFT JOIN silver.olist_orders_dataset o ON o.order_id=child.order_id LEFT JOIN gold.dim_calendario d ON d.dia=o.order_purchase_timestamp::date;
