SELECT json_build_object('columns',json_agg(json_build_object('table',c.relname,'name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull) ORDER BY c.relname,a.attnum))
FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_attribute a ON a.attrelid=c.oid WHERE n.nspname='gold' AND c.relname IN ('fato_pedidos','fato_itens_pedido','fato_pagamentos') AND a.attnum>0 AND NOT a.attisdropped;
SELECT json_build_object('constraints',json_agg(json_build_object('table',c.relname,'name',k.conname,'kind',k.contype,'target',CASE WHEN k.contype='f' THEN k.confrelid::regclass::text ELSE NULL END,'validated',k.convalidated,'definition',pg_get_constraintdef(k.oid)) ORDER BY c.relname,k.conname))
FROM pg_constraint k JOIN pg_class c ON c.oid=k.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='gold' AND c.relname IN ('fato_pedidos','fato_itens_pedido','fato_pagamentos');
SELECT json_build_object('upstream_tables',json_agg(json_build_object('schema',n.nspname,'name',c.relname,'oid',c.oid::bigint,'filenode',c.relfilenode::bigint) ORDER BY n.nspname,c.relname))
FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind='r' AND (n.nspname='silver' OR (n.nspname='gold' AND c.relname IN ('dim_clientes','dim_produtos','dim_vendedores','dim_calendario','dim_localizacao','dim_forma_pagamento')));
SELECT json_build_object('dimension_columns',json_agg(json_build_object('table',c.relname,'name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull) ORDER BY c.relname,a.attnum))
FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_attribute a ON a.attrelid=c.oid WHERE n.nspname='gold' AND c.relname IN ('dim_clientes','dim_produtos','dim_vendedores','dim_calendario','dim_localizacao','dim_forma_pagamento') AND a.attnum>0 AND NOT a.attisdropped;
SELECT json_build_object('dimension_constraints',json_agg(json_build_object('table',c.relname,'kind',k.contype,'definition',pg_get_constraintdef(k.oid)) ORDER BY c.relname,k.contype,k.conname))
FROM pg_constraint k JOIN pg_class c ON c.oid=k.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='gold' AND c.relname IN ('dim_clientes','dim_produtos','dim_vendedores','dim_calendario','dim_localizacao','dim_forma_pagamento');
