SELECT json_build_object('analise','pedidos_resumo','rows',coalesce(json_agg(row_to_json(q)),'[]'::json)) FROM (WITH b AS (SELECT x.order_id,x.order_status order_status,dt.dia dia_compra,date_trunc('month',dt.dia)::date mes,l.customer_state uf,l.customer_city cidade,l.membro_tipo localizacao_tipo,c.customer_unique_id FROM gold.fato_pedidos x LEFT JOIN gold.dim_calendario dt ON dt.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk LEFT JOIN gold.dim_clientes c ON c.cliente_sk=x.cliente_sk), a AS (SELECT 'geral'::text escopo,b.* FROM b UNION ALL SELECT 'delivered',b.* FROM b WHERE order_status='delivered') SELECT escopo,count(*) linhas,count(DISTINCT order_id) pedidos FROM a GROUP BY escopo) q;
