SELECT json_build_object('analise','reconciliacao_pedido_niveis','rows',coalesce(json_agg(row_to_json(q)),'[]'::json)) FROM (WITH b AS (SELECT b.*,r.itens,r.pagamentos,r.preco,r.frete,r.valor,r.diferenca FROM (SELECT x.order_id,x.order_status order_status,dt.dia dia_compra,date_trunc('month',dt.dia)::date mes,l.customer_state uf,l.customer_city cidade,l.membro_tipo localizacao_tipo,c.customer_unique_id FROM gold.fato_pedidos x LEFT JOIN gold.dim_calendario dt ON dt.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk LEFT JOIN gold.dim_clientes c ON c.cliente_sk=x.cliente_sk) b JOIN (WITH i AS (SELECT order_id,count(*) itens,sum(price) preco,sum(freight_value) frete FROM gold."fato_itens_pedido" GROUP BY order_id),
p AS (SELECT order_id,count(*) pagamentos,sum(payment_value) valor FROM gold."fato_pagamentos" GROUP BY order_id)
SELECT o.order_id,o.order_status,i.itens,p.pagamentos,i.preco,i.frete,p.valor,
 CASE WHEN i.order_id IS NULL OR p.order_id IS NULL THEN NULL ELSE p.valor-i.preco-i.frete END diferenca
FROM gold."fato_pedidos" o LEFT JOIN i ON i.order_id=o.order_id LEFT JOIN p ON p.order_id=o.order_id) r USING(order_id)), a AS (SELECT 'geral'::text escopo,b.* FROM b UNION ALL SELECT 'delivered',b.* FROM b WHERE order_status='delivered') SELECT escopo,CASE WHEN grouping(order_status)=0 THEN 'status' WHEN grouping(mes)=0 THEN 'mes' WHEN grouping(uf)=0 THEN 'uf' ELSE 'geral' END nivel,order_status,mes,uf,count(*) pedidos,count(*) FILTER(WHERE itens IS NULL) sem_itens,count(*) FILTER(WHERE pagamentos IS NULL) sem_pagamentos,count(diferenca) comparaveis,count(*) FILTER(WHERE abs(diferenca)>0.01) divergencias,count(*) FILTER(WHERE diferenca>0.01) positivas,count(*) FILTER(WHERE diferenca < -0.01) negativas,sum(preco) price,sum(frete) freight_value,sum(valor) payment_value FROM a GROUP BY escopo,GROUPING SETS((),(order_status),(mes),(uf))) q;
